import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadWadhvanaData(){const e=readFileSync(resolve(__dirname,"../../frontend/wadhvana-wetland-explorer/wadhvana-data.js"),"utf-8");return new Function(e+"\nreturn { WADHNAVANA_INFO, ECOLOGY_HYDROLOGY, BIRD_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Wadhvana Wetland Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadWadhvanaData()}),describe("WADHNAVANA_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.WADHNAVANA_INFO.id).toBe("wadhvana-wetland"),expect(e.WADHNAVANA_INFO.name).toBe("Wadhvana Wetland"),expect(e.WADHNAVANA_INFO.ramsarYear).toBe(2021),expect(e.WADHNAVANA_INFO.ramsarSiteNo).toBe(2454),expect(e.WADHNAVANA_INFO.state).toBe("Gujarat")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.WADHNAVANA_INFO.quickStats)).toBe(!0),expect(e.WADHNAVANA_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains overview, hydrology, and conservation status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.hydrology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()})}),describe("BIRD_SPECIES catalog",()=>{it("is a non-empty array of bird species",()=>{expect(Array.isArray(e.BIRD_SPECIES)).toBe(!0),expect(e.BIRD_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Ferruginous Duck and Greylag Goose",()=>{const t=e.BIRD_SPECIES.find(e=>"ferruginous-duck"===e.id),a=e.BIRD_SPECIES.find(e=>"greylag-goose"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"wadhvana-wetland"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../wadhvana-wetland-explorer/index.html")})})});